#!/usr/bin/env python3
"""Run every simulation generated by generate.py, or only the directories given as arguments.

    python3 run.py                      # all
    python3 run.py breakthrough/mpd     # a subset
"""

from pathlib import Path
from concurrent.futures import ThreadPoolExecutor, as_completed
import subprocess
import sys

ROOT = Path(__file__).resolve().parent
BINARY = ROOT.parents[3] / "build" / "ruptura"


def run_ruptura(workdir):
    print(f"Running in {workdir}", flush=True)

    log_path = workdir / "ruptura.log"
    with open(log_path, "w") as log:
        result = subprocess.run(
            [str(BINARY)],
            cwd=workdir,
            stdout=log,
            stderr=subprocess.STDOUT,
            text=True,
        )

    return {
        "dir": str(workdir.relative_to(ROOT)),
        "returncode": result.returncode,
        "log": str(log_path.relative_to(ROOT)),
    }


# Breakthroughs first, so the long MPD run starts immediately.
dirs = [ROOT / name for name in sys.argv[1:]] or sorted(
    (path.parent for path in ROOT.glob("*/*/simulation.json")),
    key=lambda path: (path.parent.name != "breakthrough", str(path)),
)

with ThreadPoolExecutor(max_workers=8) as executor:
    futures = {executor.submit(run_ruptura, d): d for d in dirs}

    for future in as_completed(futures):
        result = future.result()

        print(f"\n=== {result['dir']} ===")
        print(f"exit code: {result['returncode']}")
        print(f"log: {result['log']}", flush=True)
